/bin/bash -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Add File: vat.ts
+export function vat(amountCents: number, rate: number): number {
+  return Math.round(amountCents * rate);
+}
*** Add File: vat.test.ts
+import assert from \"node:assert/strict\";
+import test from \"node:test\";
+
+import { vat } from \"./vat.ts\";
+
+test(\"rounds VAT away from zero for negative amounts\", () => {
+  assert.equal(vat(-1000, 0.2), -200);
+  assert.equal(vat(-1005, 0.2), -201);
+  assert.equal(vat(-1015, 0.2), -203);
+  assert.equal(vat(1005, 0.2), 201);
+  assert.equal(vat(1015, 0.2), 203);
+});
*** End Patch
PATCH
node --test vat.test.ts"

